final class ShizukuRedirect{private static final String TAG=HookEntry.TAG,SHIZUKU="rikka.shizuku.Shizuku",ARGS="rikka.shizuku.Shizuku$UserServiceArgs";private ShizukuRedirect(){}static void install(ClassLoader l)throws Exception{Class<?> s=Class.forName(SHIZUKU,false,l),a=Class.forName(ARGS,false,l);XposedHelpers.findAndHookMethod(s,"bindUserService",a,android.content.ServiceConnection.class,new XC_MethodHook(){@Override protected void beforeHookedMethod(MethodHookParam p)throws Throwable{if(p.args==null||p.args.length<1||p.args[0]==null)return;Object o=p.args[0];String tag=str(o,"tag");if(!"dsh.android-shell".equals(tag))return;Object r=a.getConstructor(ComponentName.class).newInstance(new ComponentName(HookEntry.MODULE_PKG,ShellUserService.class.getName()));XposedHelpers.callMethod(r,"tag",tag);XposedHelpers.callMethod(r,"version",BuildConfig.VERSION_CODE);String process=str(o,"processName");if(process!=null)XposedHelpers.callMethod(r,"processNameSuffix",process);p.args[0]=r;XposedBridge.log(TAG+": shizuku_service module_component");}});XposedBridge.log(TAG+": shizuku_redirect installed");}private static String str(Object o,String n){try{return(String)XposedHelpers.getObjectField(o,n);}catch(Throwable e){return null;}}}
